       applyVisionOverlay(player, playerNum, mode)
    elseif md.blindOverlayActive then
        -- Only tear down (and only once) for a player who WAS affected, so we
        -- never clobber the search-mode sighted players use for foraging.
        md.blindOverlayActive = nil
        disableBlindOverlay(player, playerNum)
    end
end

local function onPlayerUpdate(player)
    updateGlow(player)
    traitBlindCheck(player)
end

local function onPlayerDeath(player)
    removeGlow(player)
    if player ~= nil then
        disableBlindOverlay(player, player:getPlayerNum())
    end
end

Events.OnPlayerUpdate.Add(onPlayerUpdate)
Events.OnPlayerDeath.Add(onPlayerDeath)

